import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.BN3Eol-0.js";const p=JSON.parse('{"title":"UXD-009 — The deep-sky viewer fits one screen; facts read label above value","description":"","frontmatter":{},"headers":[],"relativePath":"uxs/decisions/UXD-009-deep-sky-viewer-fits-one-screen.md","filePath":"uxs/decisions/UXD-009-deep-sky-viewer-fits-one-screen.md"}'),i={name:"uxs/decisions/UXD-009-deep-sky-viewer-fits-one-screen.md"};function n(r,e,l,c,d,h){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="uxd-009-—-the-deep-sky-viewer-fits-one-screen-facts-read-label-above-value" tabindex="-1">UXD-009 — The deep-sky viewer fits one screen; facts read label above value <a class="header-anchor" href="#uxd-009-—-the-deep-sky-viewer-fits-one-screen-facts-read-label-above-value" aria-label="Permalink to &quot;UXD-009 — The deep-sky viewer fits one screen; facts read label above value&quot;">​</a></h1><ul><li><strong>Status</strong>: accepted</li><li><strong>Date</strong>: 2026-11-11 (the operator&#39;s point and clarification, then the go)</li><li><strong>Decider</strong>: the operator raised G5 (&quot;italic opening text for no reason&quot;) and G6 (&quot;at the bottom, a muted line … looks like labels without real values&quot;, <code>docs/wip/2026-11-11-ux-feedback-plan.md</code> lines 99–100) and identified the screen from a screenshot: the &quot;gallery item page&quot; is the deep-sky full-screen viewer (lines 438–444). The fix is the lead&#39;s resolution under &quot;Answers (2026-11-11)&quot;. The operator, 2026-11-11 (session go after the UXD check), recorded in <code>docs/wip/2026-11-11-ux-feedback-plan.md</code>, line starting &quot;- Operator go, 2026-11-11 (session&quot; (line 460): the fixes for W6, SN2, G5/G6 and O6 &quot;are accepted as decided&quot;.</li><li><strong>Answers</strong>: G5, G6; slice F4 (deep-sky viewer fit, added after the original slice plan)</li><li><strong>Changes</strong>: the spec that will cover the gallery (no UXS covers <code>/gallery/deep-sky</code> today; see UXS-000 §Next).</li></ul><h2 id="context" tabindex="-1">Context <a class="header-anchor" href="#context" aria-label="Permalink to &quot;Context&quot;">​</a></h2><p>On <code>/gallery/deep-sky</code> (example: Mystic Mountain) the fact labels OBJECT, CONSTELLATION, DISTANCE and CAPTURED sit at the very bottom edge of the window, so their values fall below it and the row reads as labels with the values hidden (plan lines 438–441).</p><h2 id="options" tabindex="-1">Options <a class="header-anchor" href="#options" aria-label="Permalink to &quot;Options&quot;">​</a></h2><p>The sources record one fix and no alternatives.</p><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to &quot;Decision&quot;">​</a></h2><p>The viewer <strong>fits one screen</strong>: the image height is capped so the caption, the credit line and the facts row <strong>with its values</strong> are visible at 1440×900 and 1366×768 without scrolling. The facts are laid out <strong>label above value</strong>.</p><p>Same screen, other rules that already apply: the caption is a real caption, so it keeps italic at 14 px or more (<a href="./UXD-002-type-scale-and-the-11px-floor">UXD-002</a>); the facility line&#39;s teal-ish colour is slice A3 (<a href="./UXD-001-ui-accent-blue-replaces-teal">UXD-001</a>) (plan lines 443–444).</p><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to &quot;Consequences&quot;">​</a></h2><ul><li>Slice F4 (not in the first slice table; the plan names it in this answer) changes the viewer&#39;s layout. It is not yet in the plan&#39;s slice table (section F, lines 377–383), so <a href="./../CHANGE-INVENTORY">CHANGE-INVENTORY</a> carries it as F4.</li></ul><h2 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h2><p>Planned: shots at 1440×900 and 1366×768. No test guards the fit today (not checked by this document).</p><p><strong>Built and verified 2026-11-14 (slice F4, <a href="./UXD-040-gallery-viewer-fits-hub-strips-keep-text-and-one-page-note">UXD-040</a>).</strong> The figure is a two-row grid (the image takes the height the caption stack leaves) and scrolls on a phone; <code>tests/e2e/gallery.spec.ts</code> guards the fit on desktop-chromium, mobile-chromium and mobile-landscape-chromium. Pillars of Creation at 1366×768: image y 40 to 415 (375 px), first value y 582 to 602, credit line y 668 to 684, button y 694 to 728 (before: values y 768 to 788, credit y 860, button y 886 to 920, all below the window); at 1440×900 the button ends at y 860 (before: y 988 to 1022). The facts were already label above value and stay so.</p>',14)])])}const f=t(i,[["render",n]]);export{p as __pageData,f as default};
